const earnImportsRunning = `-- name: EarnImportsRunning :many
SELECT id, workspace_id, mode, source, status, file_name, file_size, columns, mapping, decisions, send_welcome, total, done_rows, stats, error, created_by, created_at, matched_at, started_at, finished_at FROM earn_imports WHERE workspace_id = $1 AND status = 'importing' ORDER BY created_at
`

func (q *Queries) EarnImportsRunning(ctx context.Context, workspaceID uuid.UUID) ([]EarnImport, error) {
	rows, err := q.db.Query(ctx, earnImportsRunning, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []EarnImport{}
	for rows.Next() {
		var i EarnImport
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Mode,
			&i.Source,
			&i.Status,
			&i.FileName,
			&i.FileSize,
			&i.Columns,
			&i.Mapping,
			&i.Decisions,
			&i.SendWelcome,
			&i.Total,
			&i.DoneRows,
			&i.Stats,
			&i.Error,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.MatchedAt,
			&i.StartedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
